package com.quotexrealvision.ai; import java.util.*; public final class PredictionEngine { private final FeatureEngine fe=new FeatureEngine(); public Signal predict(List<Candle> c,double quality){if(c==null||c.size()<10||quality<.60)return new Signal("NO EDGE",.5,0,0,Collections.singletonList("Prediction blocked until actual candle detection is reliable."));FeatureVector f=fe.extract(c);double[] p=new double[]{sig(1.5*f.x[0]-.8*f.x[1]+.9*f.x[2]),sig(1.3*f.x[5]+.7*f.x[6]),sig(1.5*f.x[9]+.8*f.x[10]),sig(1.7*f.x[13]-1.7*f.x[14]+.6*f.x[16]),sig(1.1*f.x[15]+.5*f.x[16]),sig(1.0*f.x[17]+.6*f.x[19]),sig(.8*f.x[20]+.5*f.x[21])};double u=0;for(double v:p)u+=v;u/=p.length;boolean up=u>=.5;int a=0;for(double v:p)if((v>=.5)==up)a++;double agr=(double)a/p.length;double edge=Math.abs(u-.5)*2;double conf=Math.max(0,Math.min(1,.55*edge+.25*agr+.20*quality));String lab=(conf>=.62&&Math.abs(u-.5)>=.12&&agr>=.71)?(up?"UP":"DOWN"):"NO EDGE";List<String> r=new ArrayList<>();if(f.x[5]>.15)r.add("positive momentum");if(f.x[5]<-.15)r.add("negative momentum");if(f.x[13]>.4)r.add("downside liquidity sweep proxy");if(f.x[14]>.4)r.add("upside liquidity sweep proxy");if(f.x[15]>.4)r.add("bullish engulfing-like geometry");if(f.x[15]<-.4)r.add("bearish engulfing-like geometry");if(f.x[16]>.2)r.add("lower-wick rejection");if(f.x[16]<-.2)r.add("upper-wick rejection");if(r.isEmpty())r.add("evidence not sufficiently aligned");return new Signal(lab,u,conf,agr,r);}private double sig(double z){return Maths.sigmoid(z);}}
